import React from 'react';
import { useAuth } from './AuthContext';

/**
 * AccessControl component that conditionally renders its children based on user authentication and role
 * 
 * Usage examples:
 * 1. Only render for admins:
 *    <AccessControl allowAdmin>
 *      <AdminComponent />
 *    </AccessControl>
 * 
 * 2. Render different content for admins vs guests:
 *    <AccessControl
 *      allowAdmin
 *      allowGuest
 *      fallback={<GuestView />}
 *    >
 *      <AdminView />
 *    </AccessControl>
 */
const AccessControl = ({ 
  children, 
  fallback = null, 
  allowAdmin = false, 
  allowGuest = false,
  requiresAuth = false
}) => {
  const { isAuthenticated, isAdmin, loading } = useAuth();
  
  // If still checking auth status, don't render anything yet
  if (loading) {
    return null;
  }
  
  // Admin access check
  if (allowAdmin && isAdmin) {
    return <>{children}</>;
  }
  
  // Guest access check (non-admins)
  if (allowGuest && (!requiresAuth || isAuthenticated)) {
    return <>{fallback || children}</>;
  }
  
  // No access granted based on criteria
  return null;
};

export default AccessControl;